// source: syllabus.go

/**
 * SyllabusDigest は検索結果 1 件に、詳細ページから単位数などを補ったもの。
 * AI や一覧画面が「この講義は何単位でどう評価されるか」を 1 回で把握できる粒度にする。
 */
export interface SyllabusDigest extends kyomu.SyllabusSummary {
  quota?: string;
  availability?: LectureAvailability;
  credits: number /* float64 */;
  faculty?: string;
  room?: string;
  registration_method?: string;
  teaching_format?: string;
  lecture_types?: string[];
  outline_excerpt?: string;
  grading_excerpt?: string;
  detail_error?: string;
}
/**
 * SearchResult は検索結果全体。
 */
export interface SearchResult {
  total: number /* int */; // 条件に合う全件数
  returned: number /* int */; // results の件数
  truncated: boolean; // limit で切り詰めたか
  results: SyllabusDigest[];
}
